/bin/bash -lc "python3 - <<'PY'
import gi
for lib, ver in [('Rsvg', '2.0'), ('GdkPixbuf', '2.0'), ('Pango', '1.0'), ('PangoCairo','1.0')]:
 try:
  gi.require_version(lib, ver)
  mod = __import__('gi.repository', fromlist=[lib])
  print(lib, 'available')
 except Exception as e:
  print(lib, type(e).__name__, str(e))
PY"

